namespace NhatDucSoftware.Core.Services;

public static class HomeworkSql
{
    public const string InsertAssignment = "INSERT INTO HomeworkAssignments(ClassId, TeacherId, Title, AssignedOn, Kind, Prompt, AnswerKeyText, AnswerKeyFileName, AnswerKeyDriveFileId, AnswerKeyDriveWebViewLink, DriveFolderId, PublicToken, CreatedAt) VALUES(@classId, @teacherId, @title, @assignedOn, @kind, @prompt, @answerKeyText, @answerKeyFileName, @answerKeyDriveFileId, @answerKeyDriveWebViewLink, @driveFolderId, @publicToken, @createdAt) RETURNING Id;";
    public const string AssignmentSelect = "SELECT a.Id, a.ClassId, COALESCE(c.ClassName, ''), COALESCE(co.Name, ''), COALESCE(co.Code, ''), a.TeacherId, a.Title, a.AssignedOn, a.Kind, a.Prompt, a.AnswerKeyText, a.AnswerKeyFileName, a.AnswerKeyDriveFileId, a.AnswerKeyDriveWebViewLink, a.DriveFolderId, COALESCE(a.PublicToken, '') FROM HomeworkAssignments a INNER JOIN Classes c ON c.Id = a.ClassId LEFT JOIN Courses co ON co.Id = c.CourseId ";
    public const string UpsertPendingFile = "INSERT INTO HomeworkSubmissions(AssignmentId, StudentId, PendingFileName, PendingDriveFileId, PendingDriveWebViewLink) VALUES(@assignmentId, @studentId, @pendingFileName, @pendingDriveFileId, @pendingDriveWebViewLink) ON CONFLICT (AssignmentId, StudentId) DO UPDATE SET PendingFileName = EXCLUDED.PendingFileName, PendingDriveFileId = EXCLUDED.PendingDriveFileId, PendingDriveWebViewLink = EXCLUDED.PendingDriveWebViewLink;";
    public const string SaveWrittenGrade = "UPDATE HomeworkSubmissions SET Score = @score, ShortComment = @shortComment, ReportText = @reportText, FileName = COALESCE(PendingFileName, FileName), DriveFileId = COALESCE(PendingDriveFileId, DriveFileId), DriveWebViewLink = COALESCE(PendingDriveWebViewLink, DriveWebViewLink), PendingFileName = NULL, PendingDriveFileId = NULL, PendingDriveWebViewLink = NULL, GradedAt = @gradedAt WHERE AssignmentId = @assignmentId AND StudentId = @studentId;";
    public const string SaveWrittenGradeTextOnly = "UPDATE HomeworkSubmissions SET Score = @score, ShortComment = @shortComment, ReportText = @reportText, GradedAt = @gradedAt WHERE AssignmentId = @assignmentId AND StudentId = @studentId;";
    public const string SaveSpeakingGrade = "INSERT INTO HomeworkSubmissions(AssignmentId, StudentId, Score, ShortComment, ReportText, GradedAt) VALUES(@assignmentId, @studentId, @score, @shortComment, @reportText, @gradedAt) ON CONFLICT (AssignmentId, StudentId) DO UPDATE SET Score = EXCLUDED.Score, ShortComment = EXCLUDED.ShortComment, ReportText = EXCLUDED.ReportText, GradedAt = EXCLUDED.GradedAt;";
    public const string ListForTeacher = AssignmentSelect + "WHERE a.TeacherId = @teacherId AND a.ClassId = @classId ORDER BY a.AssignedOn DESC, a.Id DESC;";
    public const string GetAssignment = AssignmentSelect + "WHERE a.Id = @id AND a.TeacherId = @teacherId;";
    public const string GetByPublicToken = AssignmentSelect + "WHERE a.PublicToken = @token;";
    public const string ListMissingPublicTokens = "SELECT Id FROM HomeworkAssignments WHERE PublicToken IS NULL OR BTRIM(PublicToken) = '';";
    public const string SetPublicToken = "UPDATE HomeworkAssignments SET PublicToken = @token WHERE Id = @id AND (PublicToken IS NULL OR BTRIM(PublicToken) = '');";
    public const string PublicTokenIndex = "CREATE UNIQUE INDEX IF NOT EXISTS UX_HomeworkAssignments_PublicToken ON HomeworkAssignments(PublicToken);";
    public const string ListRows = "SELECT s.Id, s.FullName, sub.Score, sub.ShortComment, sub.ReportText, sub.FileName, sub.DriveWebViewLink, sub.PendingFileName, sub.DriveFileId, sub.PendingDriveFileId, sub.WorkText FROM ClassStudents cs INNER JOIN Students s ON s.Id = cs.StudentId LEFT JOIN HomeworkSubmissions sub ON sub.AssignmentId = @assignmentId AND sub.StudentId = s.Id WHERE cs.ClassId = @classId ORDER BY s.FullName ASC, s.Id ASC;";
    public const string UpsertWorkText = "INSERT INTO HomeworkSubmissions(AssignmentId, StudentId, WorkText) VALUES(@assignmentId, @studentId, @workText) ON CONFLICT (AssignmentId, StudentId) DO UPDATE SET WorkText = EXCLUDED.WorkText;";
    public const string ListClassStudents = "SELECT s.Id, COALESCE(s.FullName, '') FROM ClassStudents cs INNER JOIN Students s ON s.Id = cs.StudentId WHERE cs.ClassId = @classId ORDER BY s.Id ASC;";
    public const string ListClassAssignments = "SELECT a.Id, a.TeacherId, COALESCE(a.Title, ''), a.AssignedOn, a.Kind FROM HomeworkAssignments a WHERE a.ClassId = @classId ORDER BY a.AssignedOn DESC, a.Id DESC;";
    public const string StudentInClass = "SELECT COUNT(1) FROM ClassStudents WHERE ClassId = @classId AND StudentId = @studentId;";
    public const string SetDriveFolder = "UPDATE HomeworkAssignments SET DriveFolderId = @driveFolderId WHERE Id = @id AND DriveFolderId IS NULL;";
    public const string ReplaceAnswerKeyFile = "UPDATE HomeworkAssignments SET AnswerKeyFileName = @fileName, AnswerKeyDriveFileId = @driveFileId, AnswerKeyDriveWebViewLink = @webViewLink WHERE Id = @id AND TeacherId = @teacherId;";
    public const string UpdateAnswerKeyText = "UPDATE HomeworkAssignments SET AnswerKeyText = @answerKeyText WHERE Id = @id AND TeacherId = @teacherId;";
    public const string DeleteSubmissions = "DELETE FROM HomeworkSubmissions WHERE AssignmentId IN (SELECT Id FROM HomeworkAssignments WHERE Id = @id AND TeacherId = @teacherId);";
    public const string DeleteAssignment = "DELETE FROM HomeworkAssignments WHERE Id = @id AND TeacherId = @teacherId;";
    public const string ListDriveFileIds = "SELECT AnswerKeyDriveFileId FROM HomeworkAssignments WHERE Id = @id AND TeacherId = @teacherId AND AnswerKeyDriveFileId IS NOT NULL UNION ALL SELECT s.DriveFileId FROM HomeworkSubmissions s INNER JOIN HomeworkAssignments a ON a.Id = s.AssignmentId WHERE a.Id = @id AND a.TeacherId = @teacherId AND s.DriveFileId IS NOT NULL UNION ALL SELECT s.PendingDriveFileId FROM HomeworkSubmissions s INNER JOIN HomeworkAssignments a ON a.Id = s.AssignmentId WHERE a.Id = @id AND a.TeacherId = @teacherId AND s.PendingDriveFileId IS NOT NULL;";
    public const string GetSlipToken = "SELECT COALESCE(SlipToken, '') FROM HomeworkSubmissions WHERE AssignmentId = @assignmentId AND StudentId = @studentId;";
    public const string SetSlipToken = "UPDATE HomeworkSubmissions SET SlipToken = @token WHERE AssignmentId = @assignmentId AND StudentId = @studentId AND (SlipToken IS NULL OR BTRIM(SlipToken) = '');";
    public const string AddSlipTokenColumn = "ALTER TABLE HomeworkSubmissions ADD COLUMN IF NOT EXISTS SlipToken TEXT;";
    public const string SlipTokenIndex = "CREATE UNIQUE INDEX IF NOT EXISTS UX_HomeworkSubmissions_SlipToken ON HomeworkSubmissions(SlipToken);";
    public const string GetSlipByToken = "SELECT COALESCE(st.FullName, ''), COALESCE(c.ClassName, ''), COALESCE(a.Title, ''), COALESCE(st.SlipPassword, ''), COALESCE(a.AnswerKeyText, ''), sub.Score, COALESCE(sub.ShortComment, ''), COALESCE(sub.ReportText, '') FROM HomeworkSubmissions sub INNER JOIN HomeworkAssignments a ON a.Id = sub.AssignmentId INNER JOIN Students st ON st.Id = sub.StudentId INNER JOIN Classes c ON c.Id = a.ClassId WHERE sub.SlipToken = @token;";
}
